import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForRepro,validRepro,advanceRepro,numericRepro}from './repro-models.js?v=20261023-physicscomplete01';import{showRepro}from './repro-visuals.js?v=20261023-physicscomplete01';export{showRepro};
export function mountRepro(l,p,root,{save,done,feedback}){let ts=tasksForRepro(l.widget.slice(6)),w=p.widget;w.reproTask??=ts[0].id;w.reproDrafts??={};w.reproPassed??=[];let i=ts.findIndex(t=>t.id===w.reproTask);if(i<0)i=0;let t=ts[i],v=w.reproDrafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountRepro(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.reproPassed.includes(t.id));
syncProcessMovie(l,1,['methods','evidence','graph'].includes(t.kind)?{process:false}:null);
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('reproCase','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('reproAnswer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealRepro">Reveal evidence →</button><p id="reproReadout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showRepro(t.kind,{state:c[0],neutral:t.kind==='glands',title:t.title,label:c[1],concealed:!r&&t.kind!=='glands',progress:r?1:0,step:r?5:0});$('#reproReadout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validRepro(c,v.answer);}
else if(t.type==='sequence'){body=field('reproNext','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceRepro">Advance pathway →</button><p id="reproReadout" aria-live="polite"></p>';draw=()=>{showRepro(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#reproReadout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="reproNumber">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="reproNumber" type="number" step="any" value="'+(v.number??'')+'">'+field('reproReason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);if(t.kind==='graph')body+='<label class="field-label" for="reproDay">Inspect day</label><input id="reproDay" type="range" min="1" max="28" value="'+(v.day??14)+'">';draw=()=>showRepro(t.kind,{title:t.title,day:Number(v.day??14),label:'Original illustrative evidence'});valid=()=>numericRepro(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="reproEvidence"></p><div class="lab-actions"><button class="secondary" id="recordRepro">Record reasoning</button><button class="secondary" id="nextRepro">Next challenge →</button></div><p id="reproProgress"></p>';
const status=()=>{$('#reproEvidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):w.reproPassed.includes(t.id)?'Challenge recorded.':'';$('#reproProgress').textContent=ts.filter(t=>w.reproPassed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='reproDay'){v.day=val;save();draw();return;}if(id==='reproCase'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='reproAnswer')v.answer=val;else if(id==='reproNext')v.next=val;else if(id==='reproNumber')v.number=val;else if(id==='reproReason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{if(e.target.id==='reproDay'){v.day=e.target.value;draw();}else v.number=e.target.value;save();};}
if($('#revealRepro'))$('#revealRepro').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validRepro(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validRepro(t.cases[v.case],v.answer));};
if($('#advanceRepro'))$('#advanceRepro').onclick=()=>{let n=advanceRepro(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordRepro').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);let finished=t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.reproPassed.includes(t.id))w.reproPassed.push(t.id);p.widgetDone=ts.every(t=>w.reproPassed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':'Recorded. Compare the remaining scenarios.');};$('#nextRepro').onclick=()=>{if(!w.reproPassed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.reproTask=ts[(i+1)%ts.length].id;save();remount();};}
